def cramer_random_primes(N, seed=None):
    import math, random
    if seed: random.seed(seed)
    return {n for n in range(2, N+1) if random.random() < 1/math.log(n)}

def find_product_witnesses(S, N):
    S_sorted = sorted(S)
    witnesses = []
    for i, a in enumerate(S_sorted):
        for b in S_sorted[i:]:
            if a*b > N: break
            if a*b in S: witnesses.append((a,b,a*b))
    return witnesses

def enumerate_factorizations(S, n, depth=20):
    if depth<=0: return []
    res = [[n]] if n in S else []
    for a in sorted(x for x in S if 2<=x*x<=n):
        if n%a==0:
            for sf in enumerate_factorizations(S,n//a,depth-1):
                if sf and a<=sf[0]: res.append([a]+sf)
    return res
